LOCK=R/'reading/audit/french_c2_unit06_frontier_lock.json'; PLAN=R/'reading/audit/french_c2_unit07_plan.json'; SEL=R/'reading/audit/french_c2_unit07_target_selection.json'

USE={
'langue':'Une « langue » est un système de formes et d’usages partagé par des locuteurs; traduire entre deux langues exige donc de comparer fonctions, contextes et attentes, pas seulement des mots isolés.',
'traduction':'Une « traduction » est une proposition de relation entre un texte source et un nouveau texte. Elle peut privilégier précision référentielle, rythme, registre ou effet, et doit rendre son compromis visible lorsqu’aucune option ne conserve tout.',
'traduire':'« Traduire » consiste ici à reconstruire une fonction communicative dans une autre langue. Le verbe n’implique pas qu’il existe toujours une correspondance mot à mot unique.',
'expression':'Une « expression » peut avoir un sens conventionnel qui dépasse la somme de ses mots. La reconnaître comme unité d’usage évite des équivalences littérales grammaticales mais pragmatiquement étranges.',
'adaptation':'Une « adaptation » modifie davantage la forme ou le contexte afin de préserver un effet ou une fonction. Elle devient problématique si elle efface sans le signaler une différence importante du texte de départ.',
'oreille':'L’« oreille » représente ici la perception du rythme, des sons et du naturel oral. Un choix qui paraît exact sur la page peut sembler artificiel lorsqu’il est prononcé.',
'français':'« Français » désigne ici la langue cible dans certains exemples fictifs. Le terme sert à discuter de registre et d’usage sans supposer qu’il existe une seule variété homogène du français.',
'local':'Un usage « local » appartient à un contexte géographique ou social particulier. Le traduire peut exiger une marque de différence plutôt qu’un remplacement par une coutume familière du lecteur.',
'sensible':'Un élément « sensible » demande une attention particulière parce qu’une formulation peut modifier la politesse, l’identité, la mémoire ou la relation entre groupes; la prudence ne dispense pas d’expliquer le choix.',
'délicat':'Un problème « délicat » admet plusieurs solutions défendables mais coûteuses sur des dimensions différentes. Le mot doit conduire à expliciter le compromis plutôt qu’à éviter la décision.',
'origine':'L’« origine » d’une formule indique le contexte où elle est apparue ou s’est stabilisée. Connaître cette origine peut éclairer un sens sans obliger les usages contemporains à rester identiques.',
'tradition':'Une « tradition » est une pratique ou une forme transmise et réinterprétée dans le temps. Elle n’est pas traitée comme un objet immobile ni comme une garantie d’authenticité automatique.',
'culture':'La « culture » désigne ici un ensemble hétérogène de pratiques, références et habitudes. L’analyse évite d’attribuer à toute une population une seule signification fixe.',
'village':'Le « village » d’un exemple fictif fournit un contexte concret où une formule cérémonielle possède des usages spécifiques. Il ne représente pas à lui seul une culture entière.',
'voisin':'Un « voisin » peut partager un espace sans partager les mêmes références. Cette proximité montre que la différence culturelle ne se confond pas toujours avec la distance géographique.',
'essai':'Un « essai » critique développe une interprétation en reliant exemples, critères et objections. Il ne transforme pas une préférence stylistique en preuve simplement parce qu’elle est formulée avec assurance.',
'modèle':'Un « modèle » de traduction est une manière simplifiée de décrire des priorités, par exemple proximité lexicale ou effet pragmatique. Il aide à comparer les choix sans prétendre prédire chaque phrase.',
'qualité':'La « qualité » d’une traduction dépend des critères pertinents pour sa fonction : exactitude, lisibilité, tonalité, cohérence ou traçabilité des écarts peuvent compter différemment selon le projet.',
'explication':'Une « explication » rend un choix interprétable en indiquant la difficulté, les alternatives et la raison de la solution retenue. Elle ne remplace pas le texte mais permet d’évaluer le compromis.',
'émotion':'Une « émotion » est un effet possible du texte, mais elle n’est ni entièrement programmable ni identique chez tous les lecteurs. La traduction peut préserver certains déclencheurs sans garantir une réaction uniforme.',
'échange':'Un « échange » culturel implique circulation dans plusieurs directions. Recevoir une forme étrangère peut modifier les habitudes locales autant que la forme transmise est elle-même réinterprétée.',
'transmettre':'« Transmettre » une histoire ou une formule signifie permettre sa circulation dans le temps ou entre groupes; chaque transmission peut conserver, sélectionner ou transformer certains traits.',
'occasion':'Une « occasion » est une situation où une forme culturelle est utilisée. Le même mot ou geste peut changer de fonction selon qu’il apparaît dans une cérémonie, une conversation familière ou un contexte scolaire.',
'réunir':'« Réunir » des personnes ou des versions permet une comparaison, mais la juxtaposition ne produit pas automatiquement un consensus. Les différences doivent rester visibles lorsqu’elles sont pertinentes.',
'communauté':'Une « communauté » est un groupe lié par certains usages ou institutions sans être nécessairement homogène. Une traduction responsable évite de faire parler tous ses membres d’une seule voix.'
}

EXTRA=[
"Une objection méthodologique distingue erreur et perte inévitable. Si deux langues distribuent différemment nombre, politesse, aspect ou image, une traduction peut être exacte sur le contenu principal tout en rendant moins visible une nuance. Le lecteur doit donc identifier ce qui a été perdu, ce qui a été ajouté et si l’écart modifie l’argument ou seulement sa texture.",
"Le contreargument le plus utile construit une autre version complète plutôt qu’un remplacement isolé. Une solution peut sembler meilleure phrase par phrase mais produire un registre incohérent sur l’ensemble du passage. Comparer des versions oblige à suivre les conséquences globales : voix, répétitions, ambiguïtés et relations entre personnages ou interlocuteurs.",
"Une autre tâche sépare étrangeté utile et maladresse. Conserver une structure inhabituelle peut signaler au lecteur qu’une catégorie culturelle n’a pas d’équivalent immédiat; conserver mécaniquement toute structure peut cependant rendre le texte opaque. La décision demande un critère : quelle différence doit rester perceptible pour que l’interprétation ne soit pas aplatie ?",
"La révision interprétative porte aussi sur les connaissances supposées. Une référence compréhensible dans le contexte source peut être inconnue ailleurs. On peut l’expliquer, la laisser telle quelle, la reformuler ou ajouter un paratexte. Chaque solution distribue différemment effort du lecteur, précision historique et continuité de la lecture.",
"Le passage refuse enfin l’idée qu’un contexte culturel puisse être résumé par une étiquette unique. Les usages varient selon génération, milieu, situation et individu. Une bonne explication précise l’étendue de son observation et évite de transformer un exemple local en propriété permanente d’un peuple ou d’une langue.",
"Une comparaison temporelle montre que les traductions vieillissent aussi. Un mot autrefois neutre peut changer de registre, une référence devenir plus connue, ou une forme ancienne acquérir une valeur historique. Réviser une traduction n’établit pas nécessairement que la précédente était mauvaise; le contexte de réception peut avoir changé.",
"Le dernier test demande ce qui ferait changer de choix. Si une solution est justifiée par la compréhension du lecteur, une enquête de lecture ou une contradiction interne peut affaiblir cette justification. Si elle est justifiée par la fidélité formelle, une perte de fonction systématique peut imposer une autre priorité. L’argument devient ainsi révisable au lieu d’être protégé par le goût personnel.",
"La portée reste limitée aux exemples originaux du dossier. Ils servent à exercer une méthode transférable — identifier fonction, alternative, coût et condition de révision — sans prétendre établir une règle universelle pour toutes les œuvres, toutes les langues ou toutes les communautés."
]

def h(p): return subprocess.check_output(['git','hash-object',str(p)],text=True).strip()
def fit(ps,lo,hi):
 p=list(ps); t='\n\n'.join(p); i=0
 while len(t.split())<lo and i<len(EXTRA):
  p[-1]+=' '+EXTRA[i]; i+=1; t='\n\n'.join(p)
 if not lo<=len(t.split())<=hi: raise AssertionError(f'C2 Unit07 word band {len(t.split())} not {lo}-{hi}')
 return p,t

def bridge(fs):
 return 'Révision interprétative : '+', '.join(f'« {x} »' for x in fs)+'. Ces formes de l’unité précédente sont reprises pour transférer les notions de contrôle, participation, documentation et portée vers l’analyse interculturelle.'

def qitems(s,forms):
 core=[('main_claim',s['qclaim'],s['aclaim'],[forms[0]]),('ambiguity_resolution',s['qamb'],s['aamb'],[forms[1]]),('assumption',s['qassume'],s['aassume'],[forms[2]]),('rhetorical_function',s['qrhet'],s['arhet'],[forms[3]]),('stance',s['qstance'],s['astance'],[forms[4]])]
 return core+[('vocabulary_in_context',f'Quel rôle interprétatif joue « {f} » dans ce passage ?',USE[f],[f]) for f in forms]

def make(s,forms,reviews,prior,D,lo,hi,theme):
 ps=list(s['paras']); ps[1]+=' '+' '.join(USE[f] for f in forms); ps[2]+=' '+bridge(reviews); ps,text=fit(ps,lo,hi)
 P=base.prior(prior); new=[c2base.nt(f,text,D) for f in forms]; rev=[base.rev(f,P) for f in reviews]; ids={t['form']:t['id'] for t in new+rev}; q,a=base.qa(qitems(s,forms),ids)
 return {'id':s['id'],'language':'fr','cefr':'C2','unit':7,'sequence':s['seq'],'revision':1,'title':s['title'],'passage_type':s['ptype'],'genre':s['genre'],'domains':['educational','cultural','professional'],'topics':[theme]+s['topics'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':new,'review_lexical_targets':rev,'grammar_targets':[{'id':s['id']+'-g1','role':'integration','description':'integrate modality, contrast, concessive qualification and reported interpretive alternatives'}],'discourse_targets':[{'id':s['id']+'-d1','role':'integration','description':'reconstruct translation choices, cultural scope, rival readings and explicit loss/gain tradeoffs'}],'questions':q,'answer_key':a,'speed_training':{'timed':False,'benchmark_eligible':False,'comprehension_gate':0.8,'new_word_policy':'controlled','notes':'C2 Unit07 culture, translation and interpretation.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['All source-like examples are original and fictional; no copyrighted literary passage is reproduced.']},'paired_text_group':None,'prerequisites':['French C2 Unit06'],'difficulty_notes_internal':'C2 translation equivalence, register, cultural scope, criticism and reception.','reader_tags':['unit_role:'+s['ptype'],'generation_batch','french_c2_u07']}

def specs(): return [
{'id':'fr-c2-u07-p01','seq':37,'ptype':'instructional','genre':'essay','topics':['translation equivalence','idiom','adaptation'],'title':'Préserver le sens ne signifie pas conserver chaque mot','paras':["Un texte fictif raconte qu’une personne a « posé sa tasse et fermé la porte au bruit ». Dans la langue source imaginaire, la dernière expression est conventionnelle : elle signifie qu’elle a décidé de ne plus répondre aux rumeurs. Une version mot à mot est grammaticalement possible dans la langue cible, mais un lecteur risque d’imaginer une porte réelle. Le dossier demande ce qu’une traduction doit préserver lorsque forme et fonction ne coïncident pas.","La première option garde l’image complète et accepte une étrangeté. La deuxième remplace l’expression par une formule idiomatique cible. La troisième conserve l’image mais ajoute un contexte qui rend la fonction inférable. Chacune produit une relation différente entre le lecteur et le texte.","Un contreargument soutient que remplacer l’image trahit nécessairement l’original. L’alternative répond qu’une image devenue littérale par accident peut trahir sa fonction tout autant. Révision interprétative : le choix doit distinguer une métaphore créative, dont l’étrangeté est voulue, d’une expression conventionnelle qui n’était pas saillante pour le lecteur source.","Le passage compare ensuite deux objectifs. Si l’exercice enseigne la structure de la langue source, conserver l’image peut être utile. Si le texte est une scène rapide où l’expression ne doit pas interrompre la lecture, une adaptation plus naturelle peut mieux préserver le rythme. La fonction du projet devient donc une partie du critère de qualité.","La conclusion refuse une équivalence unique définie hors contexte. Traduire exige d’indiquer quel trait est prioritaire et ce que la solution sacrifie. Une bonne justification ne prétend pas qu’aucune perte n’existe; elle montre pourquoi la perte retenue est moins importante que celle produite par les alternatives dans la situation considérée."],'qclaim':'Pourquoi le mot à mot peut-il être infidèle malgré sa proximité formelle ?','aclaim':'Parce qu’une expression conventionnelle peut devenir une image littérale et saillante dans la langue cible, modifiant la fonction qu’elle avait pour le lecteur source.','qamb':'Quelle ambiguïté du mot fidélité est centrale ?','aamb':'La fidélité peut viser les mots, l’image, le registre, la fonction ou l’effet; ces dimensions ne coïncident pas toujours.','qassume':'Quand conserver une formulation étrange devient-il plus défendable ?','aassume':'Lorsque l’étrangeté était elle-même fonctionnelle dans le texte source ou lorsque le projet veut rendre visible sa structure.','qrhet':'Pourquoi le passage propose-t-il trois versions plutôt qu’une correction unique ?','arhet':'Pour rendre comparables les pertes et les gains et montrer que le choix dépend du trait prioritaire.','qstance':'Quelle conception de la traduction est défendue ?','astance':'Une décision argumentée entre plusieurs dimensions d’équivalence, avec pertes explicites et critères liés à la fonction du projet.'},
{'id':'fr-c2-u07-p02','seq':38,'ptype':'reinforcement','genre':'reflection','topics':['oral register','regional variation','sensitive language'],'title':'Ce qui semble naturel à l’œil peut sonner faux à l’oreille','paras':["Un dialogue fictif est destiné à être joué à voix haute. La première version française est correcte sur le plan grammatical, mais tous les personnages utilisent les mêmes tournures soutenues. Lors d’une lecture, les différences d’âge, de proximité et de situation disparaissent. L’analyse porte sur la manière dont rythme et registre contribuent à l’interprétation sans réduire les personnages à des accents caricaturaux.","L’oreille détecte des répétitions et des niveaux de langue que la lecture silencieuse peut minimiser. Le français de l’exemple comporte plusieurs possibilités selon la relation entre interlocuteurs. Un choix local peut signaler une proximité précise, mais il risque d’associer un personnage source à une région cible qui n’a aucun rapport historique avec lui.","Une objection propose d’utiliser un dialecte cible très marqué pour reproduire toute différence sociale. L’alternative montre le coût : le lecteur reçoit alors des associations géographiques et culturelles ajoutées. Révision interprétative : on peut répartir la différence dans le lexique, la syntaxe, le rythme ou les formes d’adresse sans prétendre créer un équivalent sociologique exact.","Le texte traite aussi des formulations sensibles. Un terme d’époque peut être essentiel pour montrer une hiérarchie ou un préjugé; le neutraliser peut effacer un aspect du récit, tandis que le reproduire sans contexte peut être lu comme une adoption par la voix traductrice. Le choix délicat exige de distinguer personnage, narrateur, auteur fictif et dispositif éditorial.","La conclusion propose un test oral et contrastif. Plusieurs versions sont lues sans annoncer laquelle est préférée. Le lecteur décrit ce qu’il infère sur les relations et compare ces inférences aux indices du texte. La décision reste révisable si la marque de registre crée systématiquement des associations absentes ou efface une opposition importante."],'qclaim':'Pourquoi l’oralisation révèle-t-elle des problèmes que la correction grammaticale ne suffit pas à détecter ?','aclaim':'Parce que rythme, répétition, niveau de langue et relation entre voix deviennent plus perceptibles lorsqu’un dialogue est entendu.','qamb':'Quel risque apparaît lorsqu’on remplace une variété source par un dialecte cible précis ?','aamb':'On peut ajouter des associations régionales et sociales propres à la culture cible qui n’existaient pas dans le texte source.','qassume':'Pourquoi répartir le registre sur plusieurs indices peut-il être préférable ?','aassume':'Parce que cela préserve une différence relationnelle sans fabriquer une correspondance sociologique unique entre deux contextes.','qrhet':'Quel rôle joue la lecture comparative à voix haute ?','arhet':'Elle transforme l’impression de naturel en observation discutable sur le rythme, le registre et les relations perçues.','qstance':'Quelle approche le passage adopte-t-il pour les éléments sensibles ?','astance':'Préserver leur fonction historique ou narrative tout en clarifiant la voix et le contexte, plutôt que neutraliser ou reproduire mécaniquement.'},
{'id':'fr-c2-u07-p03','seq':39,'ptype':'transfer','genre':'essay','topics':['tradition','cultural scope','contextual interpretation'],'title':'Une tradition a une histoire, pas une seule définition','paras':["Dans un village fictif, une fête annuelle commence par l’échange de petits rubans. Un guide destiné aux visiteurs affirme que le ruban « représente l’unité de la communauté ». Une habitante plus âgée explique qu’à son enfance le geste marquait surtout l’accueil des nouveaux foyers, tandis que des adolescents l’utilisent maintenant aussi comme signe d’amitié. Le dossier examine ce qu’on peut dire d’une tradition lorsque ses usages évoluent.","L’origine historique d’une pratique peut éclairer sa forme sans épuiser sa signification actuelle. La culture du village n’est pas une voix unique : familles, générations et voisins attribuent des poids différents au même geste. Une description responsable distingue source historique, usage observé et interprétation proposée.","Un contreargument affirme qu’il faut choisir le sens le plus ancien comme authentique. L’alternative remarque qu’une tradition transmise n’existe précisément que parce qu’elle est rejouée par des personnes présentes. Révision interprétative : l’ancienneté peut être pertinente pour une question d’histoire, tandis que la diversité contemporaine est pertinente pour une question d’usage actuel.","Le passage imagine ensuite la traduction du guide. Remplacer le ruban par une coutume familière au lecteur rendrait la fonction plus accessible mais effacerait l’objet culturel concret. Laisser le mot sans explication préserverait la différence matérielle tout en risquant de produire une énigme inutile. Une courte reformulation peut conserver l’objet et indiquer la pluralité de ses interprétations.","La conclusion refuse deux excès : présenter la pratique comme essence intemporelle d’un groupe ou la réduire à des préférences individuelles sans continuité. La portée correcte est intermédiaire. Une tradition est une structure de transmission où certaines formes persistent, où les usages peuvent changer et où les désaccords internes constituent eux-mêmes une partie des données culturelles."],'qclaim':'Pourquoi l’origine d’une pratique ne suffit-elle pas à définir son sens actuel ?','aclaim':'Parce que les usages sont transmis et réinterprétés par des groupes et générations différents, de sorte que la continuité de forme peut coexister avec une pluralité de fonctions.','qamb':'Quelle ambiguïté du mot authentique le passage met-il en évidence ?','aamb':'Authentique peut vouloir dire ancien, historiquement documenté, encore pratiqué ou reconnu par des membres actuels; ces critères ne coïncident pas nécessairement.','qassume':'Pourquoi le guide doit-il distinguer histoire, observation et interprétation ?','aassume':'Parce que ces sources soutiennent des affirmations de portée différente et qu’une interprétation ne doit pas être présentée comme fait unique.','qrhet':'Quel rôle joue l’exemple du ruban dans la réflexion sur la traduction ?','arhet':'Il montre qu’un objet culturel concret peut être conservé tout en expliquant sa fonction, sans le remplacer automatiquement par une coutume cible.','qstance':'Quelle conception de la tradition est défendue ?','astance':'Une continuité transmise mais réinterprétée, dont les variations internes et historiques doivent rester visibles.'},
{'id':'fr-c2-u07-p04','seq':40,'ptype':'interleaved','genre':'comparative criticism','topics':['translation criticism','criteria','reader response'],'title':'Comparer deux traductions demande plus qu’un verdict de style','paras':["Deux versions originales d’un même paragraphe fictif sont proposées. La première répète trois fois le même verbe afin de suivre la structure source; la seconde varie les verbes pour produire une prose plus fluide. Des lecteurs préfèrent spontanément la seconde. L’exercice demande toutefois si la préférence suffit à établir une meilleure traduction ou si la répétition possède une fonction qui mérite d’être conservée.","L’essai critique construit d’abord un modèle simple des choix : information référentielle, cohérence des motifs, rythme et lisibilité. La qualité n’est pas réduite à une moyenne abstraite; chaque critère reçoit un poids selon la fonction du texte. Une explication justifie ensuite les écarts au lieu de cacher le compromis derrière une impression générale.","Une objection soutient que la version fluide transmet mieux l’émotion. L’alternative remarque que la répétition peut justement construire une insistance progressive que la variation efface. Révision interprétative : on cherche où l’effet se manifeste dans la structure, puis on compare une troisième version qui conserve deux répétitions et modifie la troisième.","Le passage examine aussi la réaction des lecteurs. Une préférence stable est une donnée sur la réception, mais elle ne prouve pas directement l’intention du texte source. Des lecteurs peuvent préférer une version parce qu’elle ressemble davantage aux conventions de leur langue. Cette information est pertinente pour la lisibilité et insuffisante, seule, pour juger la conservation d’un motif.","La conclusion propose une critique traçable. Pour chaque verdict, le lecteur cite une différence formelle, précise le critère mobilisé, formule une alternative et indique ce qui ferait changer l’évaluation. La critique devient ainsi plus riche qu’un classement : elle explique pourquoi une version est meilleure pour un objectif donné et quel coût accompagne cette préférence."],'qclaim':'Pourquoi une préférence de lecteur ne suffit-elle pas à établir la meilleure traduction ?','aclaim':'Parce qu’elle renseigne sur la réception mais pas automatiquement sur toutes les fonctions du texte source, comme un motif répétitif ou une structure argumentative.','qamb':'Comment le passage traite-t-il la notion de qualité ?','aamb':'Comme une évaluation selon plusieurs critères pondérés par la fonction du texte, non comme une propriété unique immédiatement observable.','qassume':'Pourquoi introduire une troisième version hybride ?','aassume':'Pour tester si une partie de la répétition peut être conservée sans imposer tous les coûts de la première version.','qrhet':'Quel rôle joue l’explication des écarts ?','arhet':'Elle rend le compromis contrôlable en reliant un changement précis à un critère et à une conséquence interprétative.','qstance':'Quelle méthode de critique est défendue ?','astance':'Une comparaison traçable de formes, fonctions, alternatives et conditions de révision plutôt qu’un verdict fondé uniquement sur le goût.'},
{'id':'fr-c2-u07-p05','seq':41,'ptype':'integration','genre':'reflection','topics':['cultural transmission','reception','community plurality'],'title':'Transmettre une histoire, c’est aussi changer le contexte qui la reçoit','paras':["Une histoire fictive circule d’abord dans une famille, puis dans une école et enfin dans une exposition bilingue. À chaque étape, le texte principal reste presque identique, mais les introductions, les questions et les attentes du public changent. Le dossier examine pourquoi la transmission culturelle n’est pas un simple transport d’un objet stable d’un groupe vers un autre.","Un échange modifie les deux côtés : le nouveau public apprend une référence, tandis que ceux qui présentent l’histoire découvrent quelles explications ils tenaient pour évidentes. Transmettre exige donc de choisir ce qui doit accompagner le récit. Une occasion scolaire peut justifier un glossaire; une exposition peut réunir plusieurs versions; une conversation familiale peut laisser certaines références implicites.","Une objection affirme que toute explication supplémentaire dénature la spontanéité de l’histoire. L’alternative montre qu’une absence totale de contexte peut produire une autre déformation lorsque le lecteur comble les lacunes avec des catégories étrangères au récit. Révision interprétative : le paratexte est évalué par ce qu’il rend visible et par ce qu’il impose.","Le mot communauté reçoit également une limite. Les membres ne partagent pas tous la même mémoire, et certains contestent la version présentée comme officielle. Montrer deux récits incompatibles ne détruit pas nécessairement la transmission; cela peut transmettre le désaccord lui-même comme fait culturel. Une synthèse unique devient trompeuse si elle efface cette pluralité documentée.","La conclusion traite la circulation comme une série de décisions révisables. Chaque nouveau contexte peut révéler une ambiguïté ou une présupposition qui n’était pas visible auparavant. La qualité de la transmission ne se mesure donc pas à l’immobilité du texte seul, mais à la possibilité de suivre ce qui a été conservé, expliqué, transformé ou laissé ouvert."],'qclaim':'Pourquoi la transmission culturelle n’est-elle pas décrite comme un simple transport ?','aclaim':'Parce que le contexte, les connaissances supposées et les besoins d’explication changent avec le public, ce qui modifie la manière dont l’histoire est reçue et présentée.','qamb':'Pourquoi ajouter du contexte peut-il à la fois aider et déformer ?','aamb':'Il peut prévenir des inférences erronées tout en imposant une interprétation trop étroite s’il présente une lecture comme unique.','qassume':'Quand présenter plusieurs versions devient-il préférable à une synthèse ?','aassume':'Lorsque le désaccord entre versions est lui-même documenté et pertinent pour comprendre la communauté ou l’histoire.','qrhet':'Quel rôle joue la comparaison famille-école-exposition ?','arhet':'Elle montre comment la fonction d’un accompagnement change selon l’occasion et les connaissances du public.','qstance':'Quelle conception de la transmission est défendue ?','astance':'Un processus traçable où contexte et réception évoluent, et où les transformations doivent être explicites et révisables.'}]

def checkpoint(groups,D,lo,hi,theme,prior):
 forms=[f for k in ['p01','p02','p03','p04','p05'] for f in groups[k]]
 ps=["Le checkpoint présente cinq courts dossiers originaux : une expression idiomatique, un dialogue à voix haute, une description de tradition, deux versions d’un paragraphe et une histoire transmise entre plusieurs publics. Le lecteur ne cherche pas une traduction unique donnée d’avance; il construit des critères et compare les coûts des alternatives.","La première tâche identifie l’unité pertinente. Révision cumulative : "+'; '.join(f'« {f} »' for f in forms)+". Un mot peut appartenir à une expression, une expression à un registre, un registre à une relation sociale et une référence à une histoire locale. Traduire au mauvais niveau peut préserver des formes tout en détruisant la fonction qui les reliait.","La deuxième tâche exige une version rivale. Pour chaque choix, le lecteur produit au moins une alternative plausible et indique ce qu’elle conserve mieux. Une objection ne compte pas si elle prétend seulement qu’une solution est mauvaise; elle doit montrer quel autre critère devient prioritaire et quelle perte nouvelle cette priorité introduit.","La troisième tâche porte sur la portée culturelle. Un exemple de village ne devient pas la définition d’une population, une préférence de lecteurs ne devient pas l’intention de tous les auteurs, et une pratique historique ne devient pas automatiquement la fonction actuelle. Le lecteur distingue observation, interprétation et généralisation.","Enfin, le checkpoint demande une règle de révision. Une traduction justifiée par le naturel oral doit être reconsidérée si elle efface une distinction stable entre voix; une adaptation justifiée par la compréhension doit être reconsidérée si elle remplace une différence culturelle importante par une fausse équivalence. La décision reste argumentée précisément parce qu’elle peut changer." ]; ps,text=fit(ps,lo,hi)
 P=base.prior(prior); rev=[base.rev(f,P) for f in forms]; ids={t['form']:t['id'] for t in rev}
 items=[('main_claim','Quelle méthode commune organise le checkpoint ?','Identifier la fonction pertinente, construire une alternative, comparer pertes et gains, limiter la portée culturelle et annoncer une condition de révision.',[forms[0]]),('ambiguity_resolution','Pourquoi l’unité de traduction peut-elle dépasser le mot ?','Parce qu’une expression, un registre ou une référence peut avoir une fonction conventionnelle qui n’est pas récupérable par la somme de traductions isolées.',[forms[3]]),('assumption','Pourquoi une lecture locale ne doit-elle pas être généralisée à toute une culture ?','Parce que le dossier observe des usages situés et une communauté hétérogène; la généralisation exigerait des données supplémentaires.',[forms[12]]),('rhetorical_function','Pourquoi construire systématiquement une version rivale ?','Pour rendre visible le critère prioritaire de chaque solution et empêcher qu’une préférence soit présentée comme nécessité.',[forms[16]]),('synthesis','Que signifie rendre une traduction révisable ?','Préciser ce qui justifie le choix et quelle observation — perte de fonction, association ajoutée ou incompréhension — ferait préférer une alternative.',[forms[24]]),('vocabulary_in_context',f'Quel rôle joue « {forms[2]} » ?',USE[forms[2]],[forms[2]]),('vocabulary_in_context',f'Quel rôle joue « {forms[8]} » ?',USE[forms[8]],[forms[8]]),('vocabulary_in_context',f'Quel rôle joue « {forms[11]} » ?',USE[forms[11]],[forms[11]]),('vocabulary_in_context',f'Quel rôle joue « {forms[18]} » ?',USE[forms[18]],[forms[18]]),('register_style','Pourquoi le mot « délicat » doit-il mener à un compromis explicite ?',USE['délicat'],['délicat'])]
 q,a=base.qa(items,ids)
 return {'id':'fr-c2-u07-p06','language':'fr','cefr':'C2','unit':7,'sequence':42,'revision':1,'title':'Checkpoint : traduire une fonction sans effacer la différence','passage_type':'checkpoint','genre':'comparative criticism','domains':['educational','cultural','professional'],'topics':[theme,'cumulative translation reasoning'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':[],'review_lexical_targets':rev,'grammar_targets':[{'id':'fr-c2-u07-p06-g1','role':'integration','description':'integrate interpretive modality, comparison, concession and scope-limited cultural claims'}],'discourse_targets':[{'id':'fr-c2-u07-p06-d1','role':'integration','description':'synthesize equivalence, register, cultural scope, criticism, transmission and revision'}],'questions':q,'answer_key':a,'speed_training':{'timed':True,'benchmark_eligible':True,'comprehension_gate':0.8,'new_word_policy':'none','notes':'C2 Unit07 zero-new checkpoint.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['Original fictional translation cases only.']},'paired_text_group':None,'prerequisites':['French C2 Unit07 P01-P05'],'difficulty_notes_internal':'C2 cumulative translation and cultural interpretation.','reader_tags':['unit_role:checkpoint','generation_batch','french_c2_u07']}

