 unit=[make(x,groups[x['id'][-3:]],reviews[x['id'][-3:]],prior,D,lo,hi,p['theme']) for x in specs()]; unit.append(checkpoint(groups,D,lo,hi,p['theme'],prior+unit)); V=Draft202012Validator(json.loads(SCHEMA.read_text(encoding='utf-8')))
